class Solution:

	def unique(self, p):
		for i in p:
			if i != '*':
				return False
		return True

	def solve(self, s, p, m, n, dp):
		if m == 0 and n == 0:
			return True
		if n == 0:
			return False
		if m == 0 and self.unique(p[:n]):
			return True
		if m == 0:
			return False
		if dp[m][n] != -1:
			return dp[m][n]
		if s[m - 1] == p[n - 1] or p[n - 1] == '?':
			dp[m][n] = self.solve(s, p, m - 1, n - 1, dp)
			return dp[m][n]
		if p[n - 1] == '*':
			flag = False
			for i in range(m + 1):
				flag = flag or self.solve(s, p, m - i, n - 1, dp)
				if flag:
					dp[m][n] = True
					return dp[m][n]
			dp[m][n] = flag
			return dp[m][n]
		dp[m][n] = False
		return dp[m][n]

	def wildCard(self, pattern, string):
		m = len(string)
		n = len(pattern)
		dp = [[-1 for _ in range(n + 1)] for _ in range(m + 1)]
		return self.solve(string, pattern, len(string), len(pattern), dp)
